    "http://localhost:8000/api/v1/web/checkout"
);

const headers = {
    "Authorization": "Bearer {YOUR_TOKEN}",
    "Idempotency-Key": "6f1c2b8e-3d4a-4c6f-9a1b-2e3f4a5b6c7d",
    "Content-Type": "application/json",
    "Accept": "application/json",
    "X-Currency": "EUR",
};

let body = {
    "items": [
        {
            "type": "product",
            "product_id": 7,
            "qty": 1
        }
    ],
    "address_id": 1,
    "address": [],
    "save_address": false,
    "shipping_method": "standard",
    "coupon_code": "AANI10",
    "customer_note": "Gift wrap please"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

