<span id="example-requests-GETapi-v1-mobile-products">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost:8000/api/v1/mobile/products?category=rings&amp;stone[]=Ruby&amp;min_price=50000&amp;max_price=200000&amp;search=solitaire&amp;featured=1&amp;new=&amp;in_stock=&amp;sort=featured&amp;per_page=12" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --header "X-Currency: EUR" \
    --data "{
    \"category\": \"architecto\",
    \"stone\": [
        \"architecto\"
    ],
    \"min_price\": 39,
    \"max_price\": 84,
    \"search\": \"z\",
    \"sort\": \"price-asc\",
    \"per_page\": 17
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/mobile/products"
);

const params = {
    "category": "rings",
    "stone[0]": "Ruby",
    "min_price": "50000",
    "max_price": "200000",
    "search": "solitaire",
    "featured": "1",
    "new": "0",
    "in_stock": "0",
    "sort": "featured",
    "per_page": "12",
};
Object.keys(params)
    .forEach(key =&gt; url.searchParams.append(key, params[key]));

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
    "X-Currency": "EUR",
};

let body = {
    "category": "architecto",
    "stone": [
        "architecto"
    ],
    "min_price": 39,
    "max_price": 84,
    "search": "z",
    "sort": "price-asc",
    "per_page": 17
};

fetch(url, {
    method: "GET",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

